svg.script:
(function(){
  var root = document.querySelector('.a6p5-root');
  if(!root){
    var scripts = document.getElementsByTagName('script');
    var s = scripts[scripts.length-1];
    root = s && s.ownerSVGElement ? s.ownerSVGElement : null;
  }
  if(!root) return;

  function Q(sel){ return root.querySelector(sel); }
  var tip = Q('#a6p5-tip');
  var statusEl = Q('#a6p5-status');
  var liveEl = Q('#a6p5-live');
  var playBtn = Q('#a6p5-btn-play');
  var resetBtn = Q('#a6p5-btn-reset');
  var bothBtn = Q('#a6p5-btn-both');
  var reduce = false;
  try {
    reduce = window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches;
  } catch(e){ reduce = false; }

  var timers = [];
  var playing = false;
  var phaseOrder = ['basal','excesso','manif','apaga'];
  var phaseIdx = 0;

  var labels = {
    basal: {
      tip1: 'Basal',
      tip2: 'Cluster em equilíbrio — ainda sem excesso',
      stroke: 'var(--a6p5-indigo, #818CF8)',
      status: 'Basal · equilíbrio local',
      live: 'Sem hiperexcitação. O cluster não está em fogo.'
    },
    excesso: {
      tip1: 'Excesso',
      tip2: 'Atividade neuronal anormal excessiva',
      stroke: 'var(--a6p5-coral, #F87171)',
      status: 'Excesso · o fogo acende',
      live: 'Hiperexcitação excessiva: excitação direta ou freio que cede — mesmo destino.'
    },
    manif: {
      tip1: 'Manifestação',
      tip2: 'O excesso vira fenótipo clínico',
      stroke: 'var(--a6p5-gold, #FBBF24)',
      status: 'Manifestação · excesso visível',
      live: 'O fogo cortical produz a crise. Não é déficit fixo: é paroxismo.'
    },
    apaga: {
      tip1: 'Bloqueio · apaga',
      tip2: 'Autolimitada — a atividade cede e melhora',
      stroke: 'var(--a6p5-teal, #2DD4BF)',
      status: 'Apaga · crise autolimitada',
      live: 'O excesso é bloqueado. Surge e vai embora — clássico das paroxísticas.'
    },
    exc: {
      tip1: 'Excitação direta',
      tip2: 'Drive excitatório eleva o cluster ao excesso',
      stroke: 'var(--a6p5-cyan, #22D3EE)',
      status: 'Porta 1 · excitação ↑',
      live: 'Excitação direta empurra o grupamento para hiperexcitação excessiva.'
    },
    inh: {
      tip1: 'Falha inibitória',
      tip2: 'O freio cede — mesmo destino de excesso',
      stroke: 'var(--a6p5-coral, #F87171)',
      status: 'Porta 2 · freio ↓',
      live: 'Sem inibição adequada o cluster dispara em excesso — mesmo fogo.'
    },
    cluster: {
      tip1: 'Cluster em fogo',
      tip2: 'Grupamento local: excesso que se apaga',
      stroke: 'var(--a6p5-gold, #FBBF24)',
      status: 'Foco · alma da crise',
      live: 'Crise = atividade neuronal anormal excessiva, autolimitada e paroxística.'
    },
    both: {
      tip1: 'Duas portas',
      tip2: 'Excitação ou falha de freio → mesmo excesso',
      stroke: 'var(--a6p5-gold, #FBBF24)',
      status: 'Duas portas · um destino',
      live: 'Não importa a porta: o destino é hiperexcitação excessiva que cede.'
    }
  };

  function clearTimers(){
    for(var i=0;i<timers.length;i++) clearTimeout(timers[i]);
    timers = [];
    playing = false;
    root.setAttribute('data-playing','0');
  }

  function setPhase(phase, keepRoute){
    if(!phase){
      root.setAttribute('data-phase','basal');
      phase = 'basal';
    } else {
      root.setAttribute('data-phase', phase);
    }
    if(!keepRoute){
      /* route may stay if exploring */
    }
    var L = labels[phase];
    if(statusEl && L){
      statusEl.textContent = L.status;
      statusEl.setAttribute('fill', L.stroke);
    }
    if(liveEl && L) liveEl.textContent = L.live;
    phaseIdx = phaseOrder.indexOf(phase);
    if(phaseIdx < 0) phaseIdx = 0;
  }

  function setRoute(route){
    if(!route){
      root.removeAttribute('data-route');
      return;
    }
    root.setAttribute('data-route', route);
  }

  function clientToSvg(cx, cy){
    var pt = root.createSVGPoint();
    pt.x = cx; pt.y = cy;
    var m = root.getScreenCTM();
    if(!m) return {x:cx, y:cy};
    var p = pt.matrixTransform(m.inverse());
    return {x:p.x, y:p.y};
  }

  function showTip(cx, cy, t1, t2, stroke){
    if(!tip) return;
    var t1el = Q('#a6p5-tip-t1');
    var t2el = Q('#a6p5-tip-t2');
    var bg = Q('#a6p5-tip-bg');
    if(t1el) t1el.textContent = t1;
    if(t2el) t2el.textContent = t2;
    if(bg) bg.setAttribute('stroke', stroke || 'var(--a6p5-gold, #FBBF24)');
    var p = clientToSvg(cx, cy);
    var w = 300, h = 58, off = 14;
    var x = p.x + off, y = p.y + off;
    if(x + w > 820) x = p.x - w - off;
    if(y + h > 620) y = p.y - h - off;
    if(x < 8) x = 8;
    if(y < 8) y = 8;
    tip.setAttribute('transform','translate('+x.toFixed(1)+','+y.toFixed(1)+')');
    tip.setAttribute('opacity','1');
    tip.setAttribute('aria-hidden','false');
  }

  function hideTip(){
    if(!tip) return;
    tip.setAttribute('opacity','0');
    tip.setAttribute('aria-hidden','true');
  }

  function runCycle(){
    clearTimers();
    playing = true;
    root.setAttribute('data-playing','1');
    setRoute('both');
    var seq = ['basal','excesso','manif','apaga','basal'];
    var i = 0;
    var stepOn = reduce ? 650 : 950;
    var stepOff = reduce ? 120 : 180;
    function next(){
      if(i >= seq.length){
        timers.push(setTimeout(function(){
          setPhase('basal', true);
          setRoute(null);
          playing = false;
          root.setAttribute('data-playing','0');
          if(statusEl){
            statusEl.textContent = 'Ciclo completo · excesso que cede';
            statusEl.setAttribute('fill','var(--a6p5-gold, #FBBF24)');
          }
          if(liveEl) liveEl.textContent = 'Excitação ou falha de freio → fogo excessivo → manifestação → apaga.';
        }, stepOff));
        return;
      }
      var ph = seq[i];
      setPhase(ph, true);
      if(ph === 'excesso' || ph === 'manif') setRoute('both');
      if(ph === 'apaga') setRoute(null);
      i++;
      timers.push(setTimeout(function(){
        timers.push(setTimeout(next, stepOff));
      }, stepOn));
    }
    next();
  }

  function bindPhase(el){
    if(!el) return;
    var ph = el.getAttribute('data-phase');
    var L = labels[ph];
    function activate(ev){
      clearTimers();
      setPhase(ph, true);
      var cx = (ev && ev.clientX != null) ? ev.clientX : el.getBoundingClientRect().left + 80;
      var cy = (ev && ev.clientY != null) ? ev.clientY : el.getBoundingClientRect().top + 24;
      if(L) showTip(cx, cy, L.tip1, L.tip2, L.stroke);
    }
    el.addEventListener('mouseenter', function(ev){
      if(playing) return;
      setPhase(ph, true);
      if(L) showTip(ev.clientX, ev.clientY, L.tip1, L.tip2, L.stroke);
    });
    el.addEventListener('mousemove', function(ev){
      if(playing) return;
      if(tip && tip.getAttribute('opacity')==='1' && L) showTip(ev.clientX, ev.clientY, L.tip1, L.tip2, L.stroke);
    });
    el.addEventListener('mouseleave', function(){
      if(playing) return;
      hideTip();
    });
    el.addEventListener('click', activate);
    el.addEventListener('focus', function(){
      if(playing) return;
      setPhase(ph, true);
      var b = el.getBoundingClientRect();
      if(L) showTip(b.left + b.width/2, b.top + b.height/2, L.tip1, L.tip2, L.stroke);
    });
    el.addEventListener('blur', function(){ if(!playing) hideTip(); });
    el.addEventListener('keydown', function(ev){
      if(ev.key==='Enter' || ev.key===' ' || ev.key==='Spacebar'){
        ev.preventDefault();
        activate(ev);
      }
    });
  }

  function bindHotspot(el, key, route){
    if(!el) return;
    var L = labels[key];
    function activate(ev){
      clearTimers();
      if(route) setRoute(route);
      if(key === 'cluster'){
        setPhase('excesso', true);
        setRoute('both');
      } else if(key === 'exc' || key === 'inh'){
        setPhase('excesso', true);
      }
      var cx = (ev && ev.clientX != null) ? ev.clientX : el.getBoundingClientRect().left + 40;
      var cy = (ev && ev.clientY != null) ? ev.clientY : el.getBoundingClientRect().top + 20;
      if(L) showTip(cx, cy, L.tip1, L.tip2, L.stroke);
      if(statusEl && L){
        statusEl.textContent = L.status;
        statusEl.setAttribute('fill', L.stroke);
      }
      if(liveEl && L) liveEl.textContent = L.live;
    }
    el.addEventListener('mouseenter', function(ev){
      if(playing) return;
      if(route) setRoute(route);
      if(key === 'cluster') setRoute('both');
      if(L) showTip(ev.clientX, ev.clientY, L.tip1, L.tip2, L.stroke);
    });
    el.addEventListener('mousemove', function(ev){
      if(playing) return;
      if(tip && tip.getAttribute('opacity')==='1' && L) showTip(ev.clientX, ev.clientY, L.tip1, L.tip2, L.stroke);
    });
    el.addEventListener('mouseleave', function(){
      if(playing) return;
      hideTip();
      if(!playing) setRoute(null);
    });
    el.addEventListener('click', activate);
    el.addEventListener('focus', function(){
      if(playing) return;
      if(route) setRoute(route);
      var b = el.getBoundingClientRect();
      if(L) showTip(b.left + b.width/2, b.top + b.height/2, L.tip1, L.tip2, L.stroke);
    });
    el.addEventListener('blur', function(){ if(!playing){ hideTip(); setRoute(null); } });
    el.addEventListener('keydown', function(ev){
      if(ev.key==='Enter' || ev.key===' ' || ev.key==='Spacebar'){
        ev.preventDefault();
        activate(ev);
      }
    });
  }

  bindPhase(Q('#a6p5-phase-basal'));
  bindPhase(Q('#a6p5-phase-excesso'));
  bindPhase(Q('#a6p5-phase-manif'));
  bindPhase(Q('#a6p5-phase-apaga'));

  bindHotspot(Q('#a6p5-hs-exc'), 'exc', 'exc');
  bindHotspot(Q('#a6p5-hs-inh'), 'inh', 'inh');
  bindHotspot(Q('#a6p5-hs-cluster'), 'cluster', null);

  function bindChip(el, key, route){
    if(!el) return;
    var L = labels[key];
    function go(ev){
      clearTimers();
      setRoute(route);
      setPhase('excesso', true);
      var cx = (ev && ev.clientX != null) ? ev.clientX : el.getBoundingClientRect().left + 40;
      var cy = (ev && ev.clientY != null) ? ev.clientY : el.getBoundingClientRect().top + 14;
      if(L) showTip(cx, cy, L.tip1, L.tip2, L.stroke);
      if(statusEl && L){
        statusEl.textContent = L.status;
        statusEl.setAttribute('fill', L.stroke);
      }
      if(liveEl && L) liveEl.textContent = L.live;
    }
    el.addEventListener('mouseenter', function(ev){
      if(playing) return;
      setRoute(route);
      if(L) showTip(ev.clientX, ev.clientY, L.tip1, L.tip2, L.stroke);
    });
    el.addEventListener('mousemove', function(ev){
      if(playing) return;
      if(tip && tip.getAttribute('opacity')==='1' && L) showTip(ev.clientX, ev.clientY, L.tip1, L.tip2, L.stroke);
    });
    el.addEventListener('mouseleave', function(){
      if(playing) return;
      hideTip();
      setRoute(null);
    });
    el.addEventListener('click', go);
    el.addEventListener('focus', function(){
      if(playing) return;
      setRoute(route);
      var b = el.getBoundingClientRect();
      if(L) showTip(b.left + b.width/2, b.top + b.height/2, L.tip1, L.tip2, L.stroke);
    });
    el.addEventListener('blur', function(){ if(!playing){ hideTip(); setRoute(null); } });
    el.addEventListener('keydown', function(ev){
      if(ev.key==='Enter' || ev.key===' ' || ev.key==='Spacebar'){ ev.preventDefault(); go(ev); }
    });
  }

  bindChip(Q('#a6p5-chip-exc'), 'exc', 'exc');
  bindChip(Q('#a6p5-chip-inh'), 'inh', 'inh');

  if(playBtn){
    playBtn.addEventListener('click', runCycle);
    playBtn.addEventListener('keydown', function(ev){
      if(ev.key==='Enter' || ev.key===' ' || ev.key==='Spacebar'){ ev.preventDefault(); runCycle(); }
    });
  }
  if(resetBtn){
    resetBtn.addEventListener('click', function(){
      clearTimers();
      setRoute(null);
      setPhase('basal', false);
      hideTip();
      if(statusEl){
        statusEl.textContent = 'Toque o cluster · as duas portas · ou rode o ciclo';
        statusEl.setAttribute('fill','var(--a6p5-muted, #94A3B8)');
      }
    });
    resetBtn.addEventListener('keydown', function(ev){
      if(ev.key==='Enter' || ev.key===' ' || ev.key==='Spacebar'){
        ev.preventDefault();
        clearTimers();
        setRoute(null);
        setPhase('basal', false);
        hideTip();
      }
    });
  }
  if(bothBtn){
    bothBtn.addEventListener('click', function(ev){
      clearTimers();
      setRoute('both');
      setPhase('excesso', true);
      var L = labels.both;
      var b = bothBtn.getBoundingClientRect();
      var cx = (ev && ev.clientX != null) ? ev.clientX : b.left + b.width/2;
      var cy = (ev && ev.clientY != null) ? ev.clientY : b.top + b.height/2;
      showTip(cx, cy, L.tip1, L.tip2, L.stroke);
      if(statusEl){
        statusEl.textContent = L.status;
        statusEl.setAttribute('fill', L.stroke);
      }
      if(liveEl) liveEl.textContent = L.live;
    });
    bothBtn.addEventListener('keydown', function(ev){
      if(ev.key==='Enter' || ev.key===' ' || ev.key==='Spacebar'){
        ev.preventDefault();
        bothBtn.dispatchEvent(new Event('click'));
      }
    });
  }

  root.addEventListener('click', function(ev){
    var t = ev.target;
    if(!t) return;
    var keep = false;
    var nodes = root.querySelectorAll('.a6p5-hs, .a6p5-phase, .a6p5-btn, .a6p5-chip');
    for(var i=0;i<nodes.length;i++){
      if(nodes[i].contains(t) || nodes[i] === t){ keep = true; break; }
    }
    if(!keep) hideTip();
  });

  setPhase('basal', false);
  setRoute(null);
})();
